    public static ByteBuffer decodePercentEncodedOctets(String s, int i, ByteBuffer bb) {
        if (bb == null)
            bb = ByteBuffer.allocate(1);
        else
            ((Buffer)bb).clear();
        while (true) {
            bb.put((byte) (decodeHex(s, i++) << 4 | decodeHex(s, i++)));
            if (i == s.length()) {
                break;
            }
            if (s.charAt(i++) != '%') {
                break;
            }
            if (bb.position() == bb.capacity()) {
                ((Buffer)bb).flip();
                ByteBuffer bb_new = ByteBuffer.allocate(s.length() / 3);
                bb_new.put(bb);
                bb = bb_new;
            }
        }
        ((Buffer)bb).flip();
        return bb;
}
