    public static int indexOf(final byte[] array, final byte valueToFind, int startIndex) {
        if (array == null) {
            return ArrayUtils.INDEX_NOT_FOUND;
        }
        if (startIndex < 0) {
            startIndex = 0;
        }
        for (int i = startIndex; i < array.length; i++) {
            if (valueToFind == array[i]) {
                return i;
            }
        }
        return ArrayUtils.INDEX_NOT_FOUND;
}
}
