    private void removeUp(Node start, Node end, int dir, Set<Edge> edges)
    {
        if (start == end) {
            return;
        }
        OuterFaceCirculator circulator = start.iterator(dir);
        Node next;
        do {
            Edge edge = circulator.edgeToNext();
            edges.remove(edge);
            next = circulator.next();
        } while (next != end);
}
}
