    @Override
    public GraphPath<V, E> getTour(Graph<V, E> graph)
    {
        checkGraph(graph);
        List<V> vertices = new ArrayList<>(graph.vertexSet());
        if (vertices.size() == 1) {
            return getSingletonTour(graph);
        }
        Collections.shuffle(vertices, rng);
        return vertexListToTour(vertices, graph);
}
}
