    @Override
    public void clear()
    {
        if (!isEmpty()) {
            ListNodeImpl<E> node = head;
            do {
                ListNodeImpl<E> next = node.next;
                boolean removed = removeListNode(node);
                assert removed;
                node = next;
            } while (node != head);
            head = null;
            assert size == 0;
        }
}
