        public static byte[] base64DecodeToArray(final String s) {
            if (s == null) {
                return null;
            }
            int len = s.length();
            if (len == 0) {
                return new byte[0];
            }
            if (len % 4 != 0) {
                throw new IllegalArgumentException(s);
            }
            byte[] b = new byte[len / 4 * 3];
            int i = 0, j = 0, e = 0, c, tmp;
            while (i < len) {
                c = Base64.Base64Chars.indexOf(s.charAt(i++));
                tmp = c << 18;
                c = Base64.Base64Chars.indexOf(s.charAt(i++));
                tmp |= c << 12;
                c = Base64.Base64Chars.indexOf(s.charAt(i++));
                if (c < 64) {
                    tmp |= c << 6;
                    c = Base64.Base64Chars.indexOf(s.charAt(i++));
                    if (c < 64) {
                        tmp |= c;
                    } else {
                        e = 1;
                    }
                } else {
                    e = 2;
                    i++;
                }
                b[j + 2] = (byte) (tmp & 0xff);
                tmp >>= 8;
                b[j + 1] = (byte) (tmp & 0xff);
                tmp >>= 8;
                b[j + 0] = (byte) (tmp & 0xff);
                j += 3;
            }
            if (e != 0) {
                len = b.length - e;
                byte[] copy = new byte[len];
                System.arraycopy(b, 0, copy, 0, len);
                return copy;
            }
            return b;
}
}
