Class name: Boxes
    public static boolean containsPoint(Box2D box, Point2D p)
    {
        double maxX = box.getMinX() + box.getWidth();
        if (p.getX() > maxX) {
            return false;
        }
        if (p.getX() < box.getMinX()) {
            return false;
        }
        double maxY = box.getMinY() + box.getHeight();
        if (p.getY() > maxY) {
            return false;
        }
        if (p.getY() < box.getMinY()) {
            return false;
        }
        return true;
}
}
